//
// AUT 05 · E2E 04 (P0) — Plano_de_Testes_QA_MatchWallet.md §3 e §14.
// Política assumida (o plano a deixa "a aprovar"): inativar o cliente revoga o acesso na hora,
// inclusive para uma sessão já aberta. Se o produto decidir outra política, ajuste a expectativa.
// Usa conta DESCARTÁVEL criada por auto-cadastro; o admin real só executa a inativação.

describe('Plano QA · Revogação de acesso', () => {
  it('E2E 04 · admin inativa o cliente → sessão antiga e novo login deixam de funcionar', () => {
    cy.criarUsuarioDescartavel().then((conta) => {
      // Sessão "antiga": login do cliente e captura do cookie, como um segundo dispositivo.
      cy.loginComo(conta)
      cy.getCookie('access_token').its('value').as('tokenAntigo')
      cy.apiRequest({ method: 'GET', url: '/auth/me' }).its('status').should('eq', 200)

      // Admin inativa. `clearCookies` evita misturar as duas sessões no mesmo jar.
      cy.clearCookies()
      cy.loginReal('admin')
      cy.apiRequest({ method: 'PATCH', url: `/usuarios/${conta.id}`, body: { ativo: false } })
        .its('status')
        .should('be.within', 200, 299)

      // Sessão antiga reaproveitada pelo cabeçalho Cookie: precisa ser negada.
      cy.clearCookies()
      cy.get<string>('@tokenAntigo').then((token) => {
        cy.apiRequest({
          method: 'GET',
          url: '/auth/me',
          headers: { Cookie: `access_token=${token}` },
          failOnStatusCode: false,
        })
          .its('status')
          .should('be.oneOf', [401, 403])
      })

      // Novo login com a conta inativa: sem acesso.
      cy.clearCookies()
      cy.apiRequest({
        method: 'POST',
        url: '/auth/login',
        body: { email: conta.email, senha: conta.senha },
        failOnStatusCode: false,
      })
        .its('status')
        .should('be.oneOf', [401, 403])
    })
  })
})

export {}
